input.old_string:
// ===== AI 助手全屏面板（v1.16.91，输入流程迁移自已删除的 pages/ai/ai 提问页） =====

// AI搜索按钮：进入 AI 面板（无路由跳转——面板是主界面上的常驻遮罩节点，show 切显隐）
enterAiMode() {
  if (this.$app.$def.isNavigating) return
  if (this.aiMode) return
  // 保留 aiQuestion：上次未提的问题留在框里，可直接修改再问
  this.aiError = false
  this.aiPreparing = false
  this.aiMode = true
  this.log('[AI-PANEL] 进入 AI 助手面板')
},

// 退出面板（✕/左右滑/错误态返回）：清转圈与在途请求、收键盘；aiQuestion 保留供下次
exitAiMode() {
  this.aiMode = false
  this.aiPreparing = false
  this.aiError = false
  this.stopAiSpinner()
  if (this._aiVoiceTimer) { clearTimeout(this._aiVoiceTimer); this._aiVoiceTimer = null }
  if (this.aiVoiceBusy) {
    this.aiVoiceBusy = false
    this.aiMicText = '语音输入'
  }
  // 作废在途识别/问答（cancel 内含 cancelSim 清模拟定时器、清 chat 超时定时器与回调）
  getAssistant().cancel()
  this.showKeyboard = false
  this.log('[AI-PANEL] 退出 AI 助手面板')
},

// 点面板文本框：开/收键盘（复用首页 kb-wrap 三形态）。开键盘延迟 60ms 让 if 组件
// 先 mount（dataset.ux v1.16.81 同款）；准备/错误态不响应
toggleAiKeyboard() {
  if (this.aiPreparing || this.aiError) return
  if (this.showKeyboard) { this.showKeyboard = false; return }
  var self = this
  setTimeout(function() {
    if (!self.isDestroyed && self.aiMode && !self.aiPreparing && !self.aiError) {
      self.showKeyboard = true
    }
  }, 60)
},

// 面板语音输入：识别文本追加进 aiQuestion（模拟链路约 1.5s 返回；12s 超时兜底防真链路
// 手机不回包时无限卡在聆听态）
startAiVoice() {
  if (!this.aiMode || this.aiPreparing || this.aiError || this.aiVoiceBusy) return
  this.aiVoiceBusy = true
  this.aiMicText = '聆听中…'
  var self = this
  this._aiVoiceTimer = setTimeout(function() {
    if (self.isDestroyed || !self.aiVoiceBusy) return
    self.aiVoiceBusy = false
    self.aiMicText = '语音输入'
    getAssistant().cancel()
  }, 12000)
  getAssistant().recognize(function(r) {
    if (self._aiVoiceTimer) { clearTimeout(self._aiVoiceTimer); self._aiVoiceTimer = null }
    if (self.isDestroyed) return
    self.aiVoiceBusy = false
    self.aiMicText = '语音输入'
    if (!self.aiMode || self.aiPreparing || self.aiError) return
    if (r && r.ok && r.text) {
      self.aiQuestion += r.text
    }
  })
},

// 提问：准备态（转圈）→ chat() → global.aiResult → push 回答页；失败进错误态可重试
aiSubmit() {
  if (this.aiPreparing) return
  var q = (this.aiQuestion || '').trim()
  if (!q) return   // 空问题不可提问（按钮同为禁用态）
  this.showKeyboard = false
  this.aiError = false
  this.aiErrMsg = ''
  this.aiPreparing = true
  this.startAiSpinner()
  var self = this
  var searchFn = function(kw) {
    // 复用既有搜索通道（global.searchHistory → searchAllAsync → 各集引擎），同 v1.16.90 提问页
    return Promise.resolve().then(function() {
      return global.searchHistory(kw, { page: 1, pageSize: 5, category: 'all', region: 'all' })
    })
  }
  getAssistant().chat(q, searchFn, function(r) {
    // 过期回调防护：已离页/已退出面板/已被取消（aiPreparing 复位）→ 直接丢弃，
    // 防旧答案把面板从错误态/输入态拽回回答跳转
    if (self.isDestroyed || !self.aiMode || self.aiPreparing !== true) return
    self.stopAiSpinner()
    if (r && r.ok) {
      // 结果经 global 桥接传给回答页（模块实例按页面作用域隔离，不能靠页面间 import 共享）
      global.aiResult = { question: q, answer: r.answer, sources: r.sources || [] }
      self.aiPreparing = false
      // push（非 replace）：回答页返回即回主界面——AI 面板仍在输入态、问题保留可改再问
      router.push({ uri: '/pages/ai/ai-answer' })
    } else {
      self.aiPreparing = false
      self.aiError = true
      self.aiErrMsg = (r && r.reason === 'empty')
        ? '没能理解这个问题，换个说法试试'
        : 'AI 暂时不可用，请稍后再试'
    }
  })
},

// 转圈：500ms 轮换字符帧（CSS animation 运行时支持不可靠；stopAiSpinner 清定时器）
startAiSpinner() {
  var frames = ['● ○ ○', '○ ● ○', '○ ○ ●']
  var idx = 0
  var self = this
  this.stopAiSpinner()
  this.aiSpinnerText = frames[0]
  this.aiSpinnerTimer = setInterval(function() {
    idx = (idx + 1) % frames.length
    self.aiSpinnerText = frames[idx]
  }, 500)
},

stopAiSpinner() {
  if (this.aiSpinnerTimer) {
    clearInterval(this.aiSpinnerTimer)
    this.aiSpinnerTimer = null
  }
},

// 取消准备（准备态左右滑）：清转圈 + 作废在途请求，回输入态
cancelAiPrepare() {
  this.stopAiSpinner()
  getAssistant().cancel()
  this.aiPreparing = false
},

// 面板自身滑动：准备态=取消；其他=退出 AI 模式（exitAiMode 内收键盘、保留问题）
onAiSwipe(eve) {
  if (this.aiPreparing) {
    this.cancelAiPrepare()
    return
  }
  if (eve.direction === 'left' || eve.direction === 'right') {
    this.exitAiMode()
  }
},

